insert into public.posts
  (id, slug, title, excerpt, cover_image, category, tags, body, featured, author, status, published_at, updated_at)
select
  gen_random_uuid(), v.slug, v.title, v.excerpt, v.cover_image, v.category, v.tags, v.body,
  v.featured, v.author, v.status, v.published_at, now()
from (values
  ('back-of-house-app-harmony', 'The back-of-house app we built for an aparthotel', 'Stock, changeovers and recurring jobs were living on a clipboard and three group chats. We replaced all of it with one tool.', '/photos/harmony-signage.jpg', 'build', array['apps','hospitality','operations']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel — the layout and the card on the home page are already wired up to it."},{"type":"header","level":2,"text":"The brief"},{"type":"body","text":"Every changeover depended on somebody remembering something. Linen counts lived on a clipboard, maintenance jobs lived in a group chat, and the stock order was rebuilt from scratch each week."},{"type":"imagetext","side":"left","url":"/photos/harmony-welcome.jpg","alt":"Signage and welcome graphics","text":"The first thing we did was spend a morning watching how the work actually happens — not how it was supposed to happen. Almost every feature in the finished tool came out of that morning."},{"type":"header","level":2,"text":"What we built"},{"type":"body","text":"One app. Stock levels with reorder thresholds, recurring tasks that generate themselves on a schedule, and a changeover checklist that can''t be marked done until every line is ticked."},{"type":"section","bg":"mist","heading":"The outcome","text":"The clipboard is gone and nobody argues about whose turn it was to order the towels."},{"type":"button","label":"Talk to us about a tool like this","url":"/contact/"}]', true, 'WBA', 'draft', '2026-08-12T09:00:00Z'::timestamptz),
  ('modern-web-tech-not-page-builders', 'Why we build on modern web tech, not page builders', 'Template builders are quick for the agency and expensive for you. Here''s what you''re actually buying when a site is built on one.', '/photos/town-fountains.jpg', 'build', array['websites','performance','seo']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel."},{"type":"header","level":2,"text":"The trade nobody explains"},{"type":"body","text":"A page builder saves the agency days of work. That saving is real — but it gets spent once, by them, and the cost gets paid every day afterwards, by you: in load time, in what the site can never do, and in the rebuild you''ll need in three years."},{"type":"header","level":3,"text":"Speed is a revenue number"},{"type":"body","text":"Most people reach your site on a phone, on a patchy signal, while doing something else. A heavy theme loading a dozen plugins loses a chunk of them before the page has drawn."},{"type":"section","bg":"ink","heading":"The short version","text":"Build it lean once, and it can grow. Build it on a template, and the template decides your ceiling."},{"type":"link","text":"See how a free site works","url":"/sites/"}]', false, 'WBA', 'draft', '2026-07-28T09:00:00Z'::timestamptz),
  ('menu-boards-that-read-from-the-back', 'Menu boards that read from the back of the queue', 'A café menu is a design problem with a very specific constraint: it has to be legible from eight metres away, in a hurry.', '/photos/pivaz-menu.jpg', 'create', array['print','signage','hospitality']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel."},{"type":"header","level":2,"text":"The constraint"},{"type":"body","text":"Nobody reads a menu board standing still. They read it from the back of a queue, at an angle, while deciding whether to stay. That single fact decides the type size, the contrast and the ordering."},{"type":"image","url":"/photos/pivaz-signage.jpg","alt":"Illuminated shopfront signage","caption":"Shopfront and board designed as one system, so the two don''t fight each other."},{"type":"header","level":2,"text":"What changed"},{"type":"body","text":"Fewer items per panel, prices aligned on a single axis, and the two things the café actually wants to sell sitting where the eye lands first."},{"type":"button","label":"Get your menus looked at","url":"/contact/"}]', true, 'WBA', 'draft', '2026-08-05T09:00:00Z'::timestamptz),
  ('a-brand-is-a-set-of-rules', 'A brand is a set of rules, not a logo', 'The logo is the easy part. What makes a small business look established is everything that stays the same underneath it.', '/photos/mural-you-are-loved.jpg', 'create', array['branding','design']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel."},{"type":"header","level":2,"text":"Why consistency reads as size"},{"type":"body","text":"People judge how established a business is by how consistent it looks — the same two typefaces, the same handful of colours, the same tone on the sign as on the invoice."},{"type":"imagetext","side":"right","url":"/photos/mural-weston-letters.jpg","alt":"Painted lettering mural","text":"A brand you can hand to somebody else is worth more than one that only lives in the owner''s head. Rules make it transferable."},{"type":"section","bg":"mist","heading":"The minimum useful brand","text":"Two typefaces. Three colours. One logo in three formats. A single page saying how to use them. That''s genuinely it."}]', false, 'WBA', 'draft', '2026-07-14T09:00:00Z'::timestamptz),
  ('local-seo-four-things', 'Local SEO: the four things that actually move the needle', 'Most local search advice is filler. For a business with one location, almost all of the result comes from four things.', '/photos/high-street.jpg', 'grow', array['seo','local','google']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel."},{"type":"header","level":2,"text":"1. Your Google Business profile"},{"type":"body","text":"Complete, categorised correctly, with real photos and accurate hours. This is the single highest-return hour of work available to a local business."},{"type":"header","level":2,"text":"2. Reviews, steadily"},{"type":"body","text":"A trickle every month beats a burst once a year. Recency counts, and a dead review feed reads as a dead business."},{"type":"header","level":2,"text":"3. Being consistent about your name and address"},{"type":"body","text":"The same business name, address and phone number everywhere it appears. Mismatches are the most common quiet problem we find."},{"type":"header","level":2,"text":"4. A page per thing you actually do"},{"type":"body","text":"One page listing nine services will lose to nine pages that each do one properly."},{"type":"section","bg":"ink","heading":"Everything else","text":"Is optimisation on top of these four. Do them first."},{"type":"button","label":"Have us look at yours","url":"/contact/"}]', true, 'WBA', 'draft', '2026-08-18T09:00:00Z'::timestamptz),
  ('what-we-measure', 'What we measure, and what we ignore', 'A dashboard can be busy and useless at the same time. These are the handful of numbers we actually report on.', '/photos/marine-lake-reeds.jpg', 'grow', array['analytics','reporting']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel."},{"type":"header","level":2,"text":"The ones that matter"},{"type":"body","text":"Enquiries. Where they came from. What it cost to get them. Almost everything else is a vanity metric with a nice-looking graph attached."},{"type":"header","level":3,"text":"Impressions are not customers"},{"type":"body","text":"A number with lots of digits in it is not the same as a number that pays wages. If a report leads with reach, ask what it converted into."},{"type":"link","text":"How we report","url":"/services/#grow"}]', false, 'WBA', 'draft', '2026-07-02T09:00:00Z'::timestamptz),
  ('why-we-build-sites-for-free', 'Why we build websites for free', 'It isn''t a loss leader and it isn''t a trick. It''s the most honest way we found to start a long relationship with a local business.', '/photos/captains-cabin-street.jpg', '', array['mission','free sites']::text[], '[{"type":"body","text":"**Placeholder post.** Replace this copy in the admin panel."},{"type":"header","level":2,"text":"The barrier is the price, not the interest"},{"type":"body","text":"Almost every business owner we speak to wants a decent website. What stops them is a quote with a comma in it, arriving at exactly the wrong month."},{"type":"section","bg":"mist","heading":"The honest version","text":"If the spend won''t come back, we''d rather say so than sell it."},{"type":"header","level":2,"text":"What we get out of it"},{"type":"body","text":"A relationship instead of a transaction. We''d rather look after fifty local businesses for years than build fifty sites once and never speak to them again."},{"type":"button","label":"Get a free site","url":"/sites/"}]', false, 'WBA', 'draft', '2026-06-20T09:00:00Z'::timestamptz)
) as v(slug, title, excerpt, cover_image, category, tags, body, featured, author, status, published_at)
on conflict (slug) do update set
  title       = excluded.title,
  excerpt     = excluded.excerpt,
  cover_image = excluded.cover_image,
  category    = excluded.category,
  tags        = excluded.tags,
  body        = excluded.body,
  featured    = excluded.featured,
  author      = excluded.author,
  status      = excluded.status,
  updated_at  = now();
